INSERT INTO `templates` (`id`, `title`, `description`, `sections`, `is_active`, `created_by`, `created_by_name`, `created_at`, `updated_at`, `standard_key`) VALUES ('15f00c0e-2c1e-44b8-b051-27c2914f4c12','Audit industriel — Usine S2I','Trame standard pour les audits usine : ventes, ordres de fabrication, machines/moules, matières premières, rebuts, recouvrement, RH et sécurité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"27f09ffd-5aa6-4308-9e53-d79d4ad51b1a\",\"label\":\"Ventes et chiffre d\'affaires\",\"questions\":[{\"id\":\"f9536f62-b733-4afa-8b09-84507fd4e7ac\",\"text\":\"L\'évolution du chiffre d\'affaires du mois est-elle conforme aux objectifs ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"a47214ad-9e4c-46d8-9bbd-cbcb64d7b3ad\",\"text\":\"Précisez les écarts constatés et leurs causes (perte de clients, nouveaux clients…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"f9536f62-b733-4afa-8b09-84507fd4e7ac\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"23de320e-f11b-4f13-83eb-2f35976ba25b\",\"text\":\"Des clients majeurs ont-ils réduit ou arrêté leurs commandes ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"a4aa5276-39d6-481f-b373-3639d82f1300\",\"text\":\"Précisez les clients concernés et le plan d\'action commercial\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"23de320e-f11b-4f13-83eb-2f35976ba25b\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"6d1bb21f-41dd-4029-a173-f6ac7561fa21\",\"label\":\"Ordres de fabrication et sorties matière\",\"questions\":[{\"id\":\"3dd17ed7-488f-4047-98e0-ff7ed96ea798\",\"text\":\"Les ordres de fabrication et bons de sortie matière première sont-ils tous enregistrés et cohérents ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"9008d63a-dbec-4d80-98e1-c91c7761042c\",\"text\":\"Précisez les écarts ou retards de saisie constatés et la cause (absence, surcharge…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"3dd17ed7-488f-4047-98e0-ff7ed96ea798\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"2e906acb-a99b-42ea-839d-8f2b0cb0de43\",\"label\":\"État des machines et moules\",\"questions\":[{\"id\":\"74d3ff59-07a3-4342-b3e8-6ff2d7217537\",\"text\":\"Les machines et moules sont-ils en bon état de fonctionnement ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"97d8baad-35d9-489b-9ee5-aff4ca9cfbc1\",\"text\":\"Détail des pannes constatées (machine, pièce, durée) et plan d\'action\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"74d3ff59-07a3-4342-b3e8-6ff2d7217537\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"b5c04f62-a046-409f-8ab5-ba43985d8a9e\",\"text\":\"Nombre de machines à l\'arrêt lors de la visite\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false}]},{\"id\":\"194e85f0-e48a-4b8d-a4bc-4ca6ae3a4e9f\",\"label\":\"Inventaire matières premières\",\"questions\":[{\"id\":\"a107dcf8-6ae9-4fa6-8678-bde56672eaf4\",\"text\":\"Le stock physique de matières premières correspond-il aux données système ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"54a10f00-e488-40ec-b4f6-012fc85d3fd1\",\"text\":\"Précisez les articles et quantités en écart\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"a107dcf8-6ae9-4fa6-8678-bde56672eaf4\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"61c3d449-9bdc-4817-940d-d521580f0f82\",\"label\":\"Rebuts et déchets\",\"questions\":[{\"id\":\"0009cc1a-587a-4510-84be-b18b6a214416\",\"text\":\"Le taux de rebuts constaté est-il dans la norme attendue ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"b6f4c391-0343-414f-837a-d476639dad29\",\"text\":\"Taux de rebuts constaté (%)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"0009cc1a-587a-4510-84be-b18b6a214416\",\"triggerValues\":[\"no\"]}},{\"id\":\"22fb5962-f9ea-4741-8783-8398d41e0a6f\",\"text\":\"Le stock de déchets à vendre est-il suivi et écoulé régulièrement ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]},{\"id\":\"fe752735-eb98-472f-a665-6fdacf9e1608\",\"label\":\"Suivi balance client et recouvrement\",\"questions\":[{\"id\":\"e61e821f-bbd3-4583-9b5b-e1ec88534c67\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"3af39c2c-b4e7-4b08-a4b5-c71e510a70c9\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"0b3a05cb-faa5-436c-9b3a-e05483839ebb\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"e61e821f-bbd3-4583-9b5b-e1ec88534c67\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"052c6bda-1862-447b-8d4e-666eeb1cfa35\",\"label\":\"Organisation et climat social\",\"questions\":[{\"id\":\"0aa1ce70-d14d-4eaf-9f7f-90a5ead02847\",\"text\":\"Les effectifs (production, administratif) sont-ils suffisants ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"5de763bf-fcbb-4a5f-8922-60a39eda704f\",\"text\":\"Précisez les postes en tension et les recommandations\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"0aa1ce70-d14d-4eaf-9f7f-90a5ead02847\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"6a76b63b-b724-4572-8a50-28e70d31788e\",\"text\":\"Un conflit ou climat social tendu a-t-il été observé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"254da6c0-957b-4544-83ca-196419d01162\",\"text\":\"Détail du conflit constaté et mesures recommandées\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"6a76b63b-b724-4572-8a50-28e70d31788e\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"35d22763-f407-4ae2-ac4f-2d98bad5cea4\",\"label\":\"Hygiène, sécurité et environnement usine\",\"questions\":[{\"id\":\"7ddf5d10-a143-4623-859b-4fcdb0d65941\",\"text\":\"L\'état de propreté de l\'usine est-il satisfaisant ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true},{\"id\":\"abc6c6c2-72e5-4bc2-84ee-01820902f195\",\"text\":\"Les équipements de sécurité (extincteurs, caméras) sont-ils opérationnels et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"7db141b1-fcc3-41d4-b749-beed849cde6c\",\"text\":\"Précisez les anomalies constatées et les actions correctives\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"abc6c6c2-72e5-4bc2-84ee-01820902f195\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"4f27abfb-889d-496e-b8cd-bd3cd5017e76\",\"text\":\"Le matériel informatique (postes, imprimantes) est-il suffisant et fonctionnel ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'admin@s2i.local','Administrateur Audit','2026-10-21T09:09:57.331Z','2026-10-21T09:09:57.331Z','usine'),
('c7404675-dc69-48c8-b372-15709afe0551','Audit logistique et commercial — Dépôt','Trame standard pour les audits dépôt : inventaire stock, clôture de caisse, facturation/livraison, retours clients, organisation et recouvrement. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"75098411-5896-400a-914f-9528f8677011\",\"label\":\"Inventaire stock dépôt\",\"questions\":[{\"id\":\"bcc0fca9-5aea-4528-ad40-1f35d3c1ab58\",\"text\":\"Le stock physique correspond-il au stock système (PROXIM/PROMOFOOD/BEESKY) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"c19315c1-c209-490e-b95a-8743a6fae8cd\",\"text\":\"Précisez la nature et la valeur de l\'écart constaté (article, quantité, montant)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"bcc0fca9-5aea-4528-ad40-1f35d3c1ab58\",\"triggerValues\":[\"no\"]}},{\"id\":\"d2471b73-ea02-45ab-af06-1db87916ce2e\",\"text\":\"Des articles endommagés ou périmés ont-ils été identifiés ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"66677d9a-ca6e-4c44-b56a-0579bdb28cdc\",\"text\":\"Détail des articles concernés et prix de liquidation proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"d2471b73-ea02-45ab-af06-1db87916ce2e\",\"triggerValues\":[\"yes\"]}},{\"id\":\"a4980c3a-54e7-4835-81d4-ecd23e8d236e\",\"text\":\"Les mouvements de stock (transferts entre dépôts, gestes commerciaux) sont-ils tracés formellement ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"154dd107-46ae-45cc-9bee-bb7f7d8e32f8\",\"text\":\"Précisez les manques de traçabilité constatés\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"a4980c3a-54e7-4835-81d4-ecd23e8d236e\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"f38b5590-a022-46ee-8e5a-31f139cea494\",\"label\":\"Clôture de caisse et inventaire véhicule (agents commerciaux)\",\"questions\":[{\"id\":\"728c210e-5b6d-444a-8be1-6d22408150fb\",\"text\":\"Un écart a-t-il été constaté entre le système (NOMADIS) et les espèces encaissées ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"8670b15a-2463-4bd6-bb7b-2f971f723cbc\",\"text\":\"Montant de l\'écart constaté (DT)\",\"type\":\"NUMBER\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"728c210e-5b6d-444a-8be1-6d22408150fb\",\"triggerValues\":[\"yes\"]}},{\"id\":\"03b3e2ec-78f5-4713-a4f9-88bc7ac9356d\",\"text\":\"Un justificatif a-t-il été présenté par l\'agent ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"728c210e-5b6d-444a-8be1-6d22408150fb\",\"triggerValues\":[\"yes\"]}},{\"id\":\"516a86d6-8ed1-4d08-86fe-2c8aa8e8eec2\",\"text\":\"L\'écart a-t-il été régularisé immédiatement ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"728c210e-5b6d-444a-8be1-6d22408150fb\",\"triggerValues\":[\"yes\"]}},{\"id\":\"0b57b229-46db-4f2e-b6c5-c1c90a63b92a\",\"text\":\"Un écart a-t-il été constaté lors de l\'inventaire du stock véhicule ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"42a79996-d59a-4ee7-ae63-3038e05422de\",\"text\":\"Montant/quantité de l\'écart et régularisation effectuée\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"0b57b229-46db-4f2e-b6c5-c1c90a63b92a\",\"triggerValues\":[\"yes\"]}}]},{\"id\":\"825e7403-2b8d-4e36-a836-07070e3917ee\",\"label\":\"Facturation, livraison et retours clients\",\"questions\":[{\"id\":\"fd366b4f-9489-4850-aa87-e66d8e24a371\",\"text\":\"Les livraisons sont-elles systématiquement facturées avant sortie de marchandise ?\",\"type\":\"SCALE\",\"weight\":3,\"required\":true},{\"id\":\"c5a5b631-3a57-4122-80f9-8e0035f0e411\",\"text\":\"Précisez les cas de livraison sans facturation préalable et la régularisation effectuée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"fd366b4f-9489-4850-aa87-e66d8e24a371\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"c53a25d6-451b-423d-8b0f-916135952e5e\",\"text\":\"Les remises accordées sont-elles validées officiellement avant application ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"862c9dcc-517a-4667-a632-fc69e9f2bd59\",\"text\":\"Les retours clients sont-ils traités selon la procédure (déclaration, validation direction) ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"d8189f4a-e778-4ce8-9ebf-bb7cf65646e0\",\"text\":\"Précisez les retours en attente et l\'origine du blocage\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"862c9dcc-517a-4667-a632-fc69e9f2bd59\",\"triggerValues\":[\"rarely\",\"never\"]}}]},{\"id\":\"669d8ce5-1c0e-4a09-a4a8-13420659bb2e\",\"label\":\"Organisation et ressources humaines\",\"questions\":[{\"id\":\"87ff89a3-9814-4476-a508-a1b6a39f4d16\",\"text\":\"Les effectifs administratifs sont-ils suffisants pour les tâches du dépôt ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"f505eb0e-24b3-4f17-b68c-e517e484aef6\",\"text\":\"Précisez les tâches impactées et les recommandations (recrutement, réorganisation…)\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"87ff89a3-9814-4476-a508-a1b6a39f4d16\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"86ead154-23a8-49c0-bba8-b51c5353f563\",\"text\":\"Un organigramme clair et une répartition des tâches sont-ils en place ?\",\"type\":\"YES_NO\",\"weight\":1,\"required\":true}]},{\"id\":\"f81f5e9b-b0d5-45a2-a12e-bd58f2e715ec\",\"label\":\"Suivi balance client, recouvrement et effets\",\"questions\":[{\"id\":\"ac24961a-5be0-47fd-adca-c9d4dbc05d08\",\"text\":\"Les créances clients sont-elles suivies et à jour ?\",\"type\":\"SCALE\",\"weight\":2,\"required\":true},{\"id\":\"82b99d4b-4c6f-47e1-91ae-7225c584d038\",\"text\":\"Montant total des impayés significatifs constatés (DT)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false},{\"id\":\"4291a51a-52c0-46e9-9459-445679d15f64\",\"text\":\"Plan d\'action de recouvrement proposé\",\"type\":\"TEXT\",\"weight\":1,\"required\":true,\"dependsOn\":{\"questionId\":\"ac24961a-5be0-47fd-adca-c9d4dbc05d08\",\"triggerValues\":[\"rarely\",\"never\"]}},{\"id\":\"a84387ec-2e70-4571-94fe-e73faa8cff9b\",\"text\":\"La gestion des effets (traites, échéances) est-elle rigoureuse et à jour ?\",\"type\":\"SCALE\",\"weight\":1,\"required\":true}]}]',0,'admin@s2i.local','Administrateur Audit','2026-10-21T09:09:57.334Z','2026-10-21T09:09:57.334Z','depot'),
('d5f6d503-9369-40be-8551-6ea3f9be0b52','Audit logistique — Déchargement de containers importés','Grille de contrôle standard pour le déchargement des containers importés : contrôle documentaire avant ouverture, inspection de l\'état général, comptage contradictoire et DLC, procédure en cas de non-conformité. Dupliquez-le pour créer un nouveau formulaire à partir de cette base.','[{\"id\":\"f68a40b7-d0e2-4696-8264-a6743b2b58bb\",\"label\":\"Contrôle documentaire (avant ouverture)\",\"questions\":[{\"id\":\"3a645c08-1478-4718-b97d-0abed2608f1a\",\"text\":\"Le Bill of Lading est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"bbb719b6-cfee-47af-a78c-a42312964228\",\"text\":\"Précisez l\'anomalie constatée sur le Bill of Lading\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"3a645c08-1478-4718-b97d-0abed2608f1a\",\"triggerValues\":[\"no\"]}},{\"id\":\"76968cea-16a1-40fc-b819-5b076a656aa9\",\"text\":\"Le certificat sanitaire est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"a2e034d2-8d61-4d60-9753-c006aa60fdc5\",\"text\":\"Précisez l\'anomalie constatée sur le certificat sanitaire\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"76968cea-16a1-40fc-b819-5b076a656aa9\",\"triggerValues\":[\"no\"]}},{\"id\":\"02e5379c-2b23-4da6-bb17-175da591c584\",\"text\":\"Le certificat d\'origine est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"6e1e055c-9f21-4a2e-a7ad-b7d137cbf2b6\",\"text\":\"Précisez l\'anomalie constatée sur le certificat d\'origine\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"02e5379c-2b23-4da6-bb17-175da591c584\",\"triggerValues\":[\"no\"]}},{\"id\":\"b9203fe1-4bd3-4dfb-be00-aeb9672f5ae8\",\"text\":\"Le Packing List est-il conforme et disponible ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"dd8fef78-68e6-4406-9ad6-929daeb49a21\",\"text\":\"Précisez l\'anomalie constatée sur le Packing List\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"b9203fe1-4bd3-4dfb-be00-aeb9672f5ae8\",\"triggerValues\":[\"no\"]}},{\"id\":\"0f8e81ce-4ca3-457e-bf50-66690978732a\",\"text\":\"Autres documents contrôlés (facture, etc.) — précisez lesquels et leur conformité\",\"type\":\"TEXT\",\"weight\":1,\"required\":false},{\"id\":\"f9ca5090-42c3-4375-835a-6cdff38f61b7\",\"text\":\"Existe-t-il un plombage identifiable et numéroté ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"2dfc90ff-f09a-43ef-ba8e-b54e81d3b89a\",\"text\":\"Précisez l\'anomalie constatée (absence de plombage, numéro illisible…)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"f9ca5090-42c3-4375-835a-6cdff38f61b7\",\"triggerValues\":[\"no\"]}},{\"id\":\"be596382-0d5a-47d9-a32d-643d3633c7a3\",\"text\":\"Numéro du plombage relevé\",\"type\":\"TEXT\",\"weight\":1,\"required\":false}]},{\"id\":\"6f743f13-21ad-45a6-a935-a0a9bc64c20a\",\"label\":\"Inspection de l\'état général du container\",\"questions\":[{\"id\":\"2ebe61ce-b8c9-43ee-965a-97346e59642c\",\"text\":\"Le container est-il intact (absence d\'ouvertures ou de fuites) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"29805913-cefd-43c1-a1ae-f30b361aa661\",\"text\":\"Précisez l\'ouverture ou la fuite constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"2ebe61ce-b8c9-43ee-965a-97346e59642c\",\"triggerValues\":[\"no\"]}},{\"id\":\"89929948-ae5b-4089-8858-0654dc23a14e\",\"text\":\"L\'ouverture des portes du container ne révèle-t-elle aucune anomalie ou suspicion ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"0833170b-3596-4cbe-841b-c04880fb7f06\",\"text\":\"Précisez l\'anomalie ou la suspicion constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"89929948-ae5b-4089-8858-0654dc23a14e\",\"triggerValues\":[\"no\"]}},{\"id\":\"c7046193-421d-4a1a-a7bf-1723bc35951e\",\"text\":\"Le contrôle visuel initial confirme-t-il qu\'aucun carton ou sac n\'est ouvert ou endommagé ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"9f7ea3b4-9a23-4912-addb-8f76e38c35b9\",\"text\":\"Précisez les cartons/sacs ouverts ou endommagés constatés\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"c7046193-421d-4a1a-a7bf-1723bc35951e\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"d98ab0b6-397b-4ee7-893d-b4c347c2dee7\",\"label\":\"Opérations de déchargement et traçabilité\",\"questions\":[{\"id\":\"ad3e06cc-44d8-457c-90b1-0afcfa9762fd\",\"text\":\"Le comptage contradictoire correspond-il au Packing List (et aux autres documents : facture, Bill of Lading) ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"8107a73a-e97f-4161-8f2d-7feeefc8d539\",\"text\":\"Précisez l\'écart constaté (référence, quantité)\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"ad3e06cc-44d8-457c-90b1-0afcfa9762fd\",\"triggerValues\":[\"no\"]}},{\"id\":\"a3518723-467f-4355-819d-eeb49dbfe8c9\",\"text\":\"Écart de quantité constaté (unités)\",\"type\":\"NUMBER\",\"weight\":1,\"required\":false,\"dependsOn\":{\"questionId\":\"ad3e06cc-44d8-457c-90b1-0afcfa9762fd\",\"triggerValues\":[\"no\"]}},{\"id\":\"42b561ab-bfcb-46fc-999e-29a1aae3ee95\",\"text\":\"Le contrôle des DLC par échantillonnage est-il conforme ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true},{\"id\":\"8fde4e0e-b2ae-43e6-8eb2-d6704f1dc264\",\"text\":\"Précisez les références et DLC non conformes constatées\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"42b561ab-bfcb-46fc-999e-29a1aae3ee95\",\"triggerValues\":[\"no\"]}}]},{\"id\":\"f99f6fca-c821-4a4e-8211-dbc20009c9f5\",\"label\":\"Procédure en cas de non-conformité\",\"questions\":[{\"id\":\"ae924df6-9330-4a3f-a728-92edc6b65ed0\",\"text\":\"Une non-conformité a-t-elle été détectée durant cet audit ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true},{\"id\":\"09070322-b713-4557-a5bd-f87bfe2b9efc\",\"text\":\"Description de la non-conformité constatée\",\"type\":\"TEXT\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"ae924df6-9330-4a3f-a728-92edc6b65ed0\",\"triggerValues\":[\"yes\"]}},{\"id\":\"b2e052fa-9cda-4049-a63a-eda8dbfd3098\",\"text\":\"Des photographies horodatées ont-elles été prises (scellé cassé, marchandise endommagée, container peu rempli…) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"ae924df6-9330-4a3f-a728-92edc6b65ed0\",\"triggerValues\":[\"yes\"]}},{\"id\":\"5ab8d3b7-b069-47b9-a137-9e29783bb39e\",\"text\":\"Le lot a-t-il été bloqué en zone de quarantaine (non-conformité majeure) ?\",\"type\":\"YES_NO\",\"weight\":2,\"required\":true,\"dependsOn\":{\"questionId\":\"ae924df6-9330-4a3f-a728-92edc6b65ed0\",\"triggerValues\":[\"yes\"]}},{\"id\":\"7e6c8073-e439-4d95-a7ca-c0e1187c4e01\",\"text\":\"Une fiche de non-conformité a-t-elle été émise et transmise à la Direction des Achats ?\",\"type\":\"YES_NO\",\"weight\":3,\"required\":true,\"dependsOn\":{\"questionId\":\"ae924df6-9330-4a3f-a728-92edc6b65ed0\",\"triggerValues\":[\"yes\"]}}]}]',0,'admin@s2i.local','Administrateur Audit','2026-10-21T09:09:57.339Z','2026-10-21T09:09:57.339Z','container');
